  /**
   * Get default settings for a specific country.
   *
   * @param string $country_code
   *   The 2-letter ISO country code (case-insensitive).
   *
   * @return array|null
   *   The country settings or NULL if not found.
   *   Structure: ['zoomLevel' => int, 'coordinates' => ['longitude' => float, 'latitude' => float]]
   */
  public static function getCountryDefaults($country_code) {
    $defaults = static::getDefaults();
    $country_code = strtoupper(trim($country_code));
    return $defaults[$country_code] ?? NULL;
  }

